19: function rr(g, x, y, w, h, r) {
20:   r = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
21:   g.beginPath();
22:   g.moveTo(x + r, y);
23:   g.arcTo(x + w, y, x + w, y + h, r);
24:   g.arcTo(x + w, y + h, x, y + h, r);
25:   g.arcTo(x, y + h, x, y, r);
26:   g.arcTo(x, y, x + w, y, r);
27:   g.closePath();
28: }
29: function starPath(g, r1, r2, points = 5, rot = -Math.PI / 2) {
30:   g.beginPath();
31:   for (let i = 0; i < points * 2; i++) {
32:     const r = i % 2 === 0 ? r1 : r2;
33:     const a = rot + i * Math.PI / points;
34:     const x = Math.cos(a) * r, y = Math.sin(a) * r;
35:     i ? g.lineTo(x, y) : g.moveTo(x, y);
36:   }
37:   g.closePath();
38: }
