385:   stars = Array.from({ length: 34 }, () => ({
386:     x: rand(0, W), y: rand(arenaTop, floorY * 0.45), r: rand(0.5, 1.6) * Math.max(0.8, S),
387:     ph: rand(0, TAU), sp: rand(0.4, 1.6),
388:   }));
389:   clouds = Array.from({ length: 4 }, (_, i) => ({
390:     x: rand(-100, W), y: arenaTop + rand(30, Math.max(90, (floorY - arenaTop) * 0.35)),
391:     s: rand(0.7, 1.35) * clamp(S, 0.7, 1.2), sp: rand(3, 9), a: rand(0.1, 0.24), ph: rand(0, TAU),
392:   }));
393:   buildingsFar = []; buildingsNear = [];
394:   let x = -30;
395:   while (x < W + 60) {
396:     const w = rand(34, 88) * clamp(S, 0.8, 1.2);
397:     const h = rand(70, 190) * clamp(S, 0.8, 1.2);
398:     buildingsFar.push({ x, w, h, seed: rand(0, 100) });
399:     x += w + rand(5, 18);
400:   }
401:   x = -40;
402:   while (x < W + 60) {
403:     const w = rand(44, 110) * clamp(S, 0.8, 1.2);
404:     const h = rand(40, 130) * clamp(S, 0.8, 1.2);
405:     buildingsNear.push({ x, w, h, seed: rand(0, 100) });
406:     x += w + rand(8, 24);
407:   }
408:   ambientConfetti = Array.from({ length: 20 }, () => ({
409:     x: rand(0, W), y: rand(arenaTop, floorY), vy: rand(8, 26), vx: rand(-8, 8),
410:     rot: rand(0, TAU), spin: rand(-2, 2), w: rand(4, 8) * clamp(S, 0.7, 1.2),
411:     color: pick(['#ffd23f', '#ff5d5d', '#2ec4b6', '#ff8fab', '#fff4d8']), ph: rand(0, TAU),
412:   }));
