527:     const pIdx = Number(pad.dataset.player);
528:     const base = joyEl.querySelector('.stick-base');
529:     const knob = joyEl.querySelector('.stick-knob');
530:     const j = { el: joyEl, knob, pIdx, pointerId: null, max: 1, jumpLatch: false };
531:     joysticks.push(j);
532: 
533:     const centerOf = () => {
534:       const r = base.getBoundingClientRect();
535:       j.max = Math.max(1, r.width * 0.3);
