537:     };
538:     const setAxis = (dx, dy) => {
539:       const raw = Math.hypot(dx, dy);
540:       const scale = raw > j.max ? j.max / raw : 1;
541:       const kx = dx * scale, ky = dy * scale;
542:       knob.style.transform = `translate(-50%, -50%) translate(${kx}px, ${ky}px)`;
543:       const x = clamp(kx / j.max, -1, 1);
544:       const dead = 0.16;
545:       touchAxes[pIdx] = Math.sign(x) * clamp((Math.abs(x) - dead) / (1 - dead), 0, 1);
