547:       if (ky > j.max * 0.5) {
548:         const pp = players[pIdx];
549:         if (pp) {
550:           pp.dropThrough = 0.25;
551:           if (pp.onGround && pp.y < floorY - 1) { pp.vy = 120 * S; pp.onGround = false; }
552:         }
553:       }
554:       // jump on upward flick
555:       if (ky < -j.max * 0.5 && !j.jumpLatch) {
556:         j.jumpLatch = true;
557:         const p = players[pIdx];
558:         if (p) queueJump(p);
559:       }
560:       if (ky > -j.max * 0.25) j.jumpLatch = false;
561:     };
562:     const release = e => {
563:       if (j.pointerId === null) return;
564:       if (e && e.pointerId !== undefined && e.pointerId !== j.pointerId) return;
565:       const p = players[pIdx];
566:       if (p && p.charging) {
567:         releaseThrow(p);
568:         p.needsMove = true;
569:       }
570:       // Return the stick to the center of its player's control half.
571:       restoreJoystickPosition(joyEl);
572:       j.pointerId = null;
573:       j.jumpLatch = false;
574:       touchAxes[pIdx] = 0;
575:       joyEl.classList.remove('active');
576:       knob.style.transform = 'translate(-50%, -50%)';
577:     };
578:     j.centerOf = centerOf;
579:     j.setAxis = setAxis;
580:     j.releaseFn = release;
581:     const canUse = () => (state === 'play' || state === 'title') && !paused;
582: 
583:     joyEl.addEventListener('pointermove', e => {
584:       if (j.pointerId !== e.pointerId) return;
585:       e.preventDefault();
586:       const c = centerOf();
587:       setAxis(e.clientX - c.x, e.clientY - c.y);
