589:     joyEl.addEventListener('pointerup', release);
590:     joyEl.addEventListener('pointercancel', release);
591:     joyEl.addEventListener('lostpointercapture', release);
592:     joyEl.addEventListener('contextmenu', e => e.preventDefault());
