602:       if (!j) return;
603:       e.preventDefault();
604:       const c = j.centerOf();
605:       j.setAxis(e.clientX - c.x, e.clientY - c.y);
606:     }, { passive: false });
607:     const end = e => {
608:       const j = joysticks.find(x => x.pointerId === e.pointerId);
609:       if (!j) return;
610:       j.releaseFn(e);
611:     };
612:     window.addEventListener('pointerup', end);
613:     window.addEventListener('pointercancel', end);
614:     window.addEventListener('lostpointercapture', end);
615:   }
