617:   // Full-half touch zones: touching anywhere in a player's half activates
618:   // and floats that player's joystick at the touch point.
619:   if (!window.__bonkJoyZones) {
620:     window.__bonkJoyZones = true;
621:     window.addEventListener('pointerdown', e => {
622:       if (!((state === 'play' || state === 'title') && !paused)) return;
623:       const target = e.target;
624:       if (target && target.closest && target.closest('button, .btn, .tab, input, a, .panel')) return;
625:       const idx = e.clientX < window.innerWidth / 2 ? 0 : 1;
626:       const j = joysticks[idx];
