630:       const pad = joyEl.closest('.pad');
631:       const padRect = pad.getBoundingClientRect();
632:       const halfW = joyEl.offsetWidth / 2;
633:       const halfH = joyEl.offsetHeight / 2;
634:       const mid = window.innerWidth / 2;
635:       let cx = e.clientX, cy = e.clientY;
636:       if (idx === 0) cx = Math.max(halfW, Math.min(cx, mid - halfW));
637:       else cx = Math.max(mid + halfW, Math.min(cx, window.innerWidth - halfW));
638:       cy = Math.max(halfH, Math.min(cy, window.innerHeight - halfH));
639:       joyEl.style.removeProperty('inset');
640:       joyEl.style.position = 'absolute';
641:       joyEl.style.left = (cx - padRect.left - halfW) + 'px';
642:       joyEl.style.top = (cy - padRect.top - halfH) + 'px';
643:       joyEl.style.right = 'auto';
644:       joyEl.style.bottom = 'auto';
645:       j.pointerId = e.pointerId;
646:       joyEl.classList.add('active');
647:       try { joyEl.setPointerCapture(e.pointerId); } catch {}
648:       const c = j.centerOf();
649:       j.setAxis(e.clientX - c.x, e.clientY - c.y);
650:       e.preventDefault();
651:     }, { passive: false });
652:   }
