675: /* ------------------------------ player update ------------------------------ */
676: function updatePlayer(p, dt) {
677:   if (!p) return;
678:   // timers
679:   p.throwCd = Math.max(0, p.throwCd - dt);
680:   p.throwAnim = Math.max(0, p.throwAnim - dt);
681:   p.rageT = Math.max(0, (p.rageT || 0) - dt);
682:   p.shieldT = Math.max(0, (p.shieldT || 0) - dt);
683:   p.catchAnim = Math.max(0, p.catchAnim - dt);
684:   p.invuln = Math.max(0, p.invuln - dt);
685:   p.hitstun = Math.max(0, p.hitstun - dt);
686:   p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
687:   p.dropThrough = Math.max(0, (p.dropThrough || 0) - dt);
688:   p.blinkTimer -= dt;
689:   if (p.blinkTimer <= 0) { p.blink = 0.11; p.blinkTimer = rand(2.2, 4.8); }
690:   p.blink = Math.max(0, p.blink - dt);
691:   if (p.ko) {
692:     p.koT += dt;
693:     p.vy += gravityFor() * dt;
694:     p.x += p.vx * dt;
695:     p.y += p.vy * dt;
696:     p.vx *= Math.pow(0.2, dt);
697:     if (p.y > floorY) { p.y = floorY; p.vy = 0; p.vx *= 0.7; }
698:     p.x = clamp(p.x, arena.left + 22 * S, arena.right - 22 * S);
699:     p.onGround = p.y >= floorY - 0.5;
700:     return;
701:   }
702: 
703:   if (p.ai && (state === 'play' || state === 'title')) updateAI(p, dt);
704: 
705:   const canControl = state === 'play' && !paused;
706:   let dir = canControl ? getInputDir(p) : 0;
707:   if (p.hitstun > 0) dir = 0;
708: 
709:   // drop through platforms on down input
710:   if (state === 'play' && canControl && !p.ai) {
711:     const downHeld = (p.idx === 0 && keys.has('KeyS')) || (p.idx === 1 && keys.has('ArrowDown'));
712:     if (downHeld) {
713:       p.dropThrough = 0.2;
714:       if (p.onGround && p.y < floorY - 1) { p.vy = 120 * S; p.onGround = false; }
715:     }
716:   }
717: 
718:   // auto-charge / auto-fire for human players
719:   if (state === 'play' && canControl && !p.ai && !p.ko && p.hitstun <= 0) {
720:     const moving = Math.abs(dir) > 0.15;
721:     if (moving) {
722:       if (p.needsMove) p.needsMove = false;
723:       if (!p.charging && p.throwCd <= 0 && !p.needsMove) beginThrow(p);
724:     }
725:   }
726: 
727:   // jump buffering
728:   if (p.jumpBuffer > 0 && canControl) {
729:     if (p.onGround || p.coyote > 0) { p.wasGround = true; doJump(p, 1); p.jumpsLeft = 1; }
730:     else if (p.jumpsLeft > 0) { p.jumpsLeft--; p.wasGround = false; doJump(p, 0.88); }
731:   }
732: 
733:   const maxSp = runSpeedFor() * (p.charging ? 0.58 : 1) * (p.hitstun > 0 ? 0.5 : 1);
734:   if (dir !== 0) {
735:     p.facing = Math.sign(dir) || p.facing;
736:     p.vx += dir * 5800 * S * dt;
737:     p.vx = clamp(p.vx, -maxSp, maxSp);
738:   } else {
739:     p.vx *= Math.pow(0.0009, dt);
740:     if (Math.abs(p.vx) < 4 * S) p.vx = 0;
741:   }
742: 
743:   if (p.charging && canControl) {
744:     p.charge = Math.min(1, p.charge + dt / 1.24);
745:     p.chargeFx = (p.chargeFx || 0) - dt;
746:     if (p.chargeFx <= 0) {
747:       p.chargeFx = 0.07;
748:       const h = handPoint(p);
749:       addParticle({
750:         x: h.x + rand(-14, 14) * S, y: h.y + rand(-14, 14) * S,
751:         vx: rand(-30, 30) * S, vy: rand(-70, -10) * S,
752:         life: rand(0.2, 0.45), size: rand(2, 4.5) * S,
753:         color: P_COLORS[p.idx], kind: 'dot', grav: -60 * S, drag: 0.92,
754:       });
755:     }
756:   } else {
757:     p.charge = 0;
758:   }
759: 
760:   // physics
761:   p.wasGround = p.onGround;
762:   const prevY = p.y;
763:   p.vy += gravityFor() * dt;
764:   p.vy = Math.min(p.vy, 1900 * S);
765:   p.x += p.vx * dt;
766:   p.y += p.vy * dt;
767:   p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
768: 
769:   p.onGround = false;
770:   p.platform = null;
771:   if (p.vy >= 0 && (p.dropThrough || 0) <= 0) {
772:     for (const pl of platforms) {
773:       if (prevY <= pl.y + 2 && p.y >= pl.y && p.y <= pl.y + pl.h + 30 * S &&
774:           p.x + 14 * S > pl.x + 3 && p.x - 14 * S < pl.x + pl.w - 3) {
775:         p.y = pl.y;
776:         p.vy = 0;
777:         p.onGround = true;
778:         p.jumpsLeft = 1;
779:         p.platform = pl;
780:         break;
781:       }
782:     }
783:   }
784:   if (p.y >= floorY) {
785:     p.y = floorY;
786:     p.vy = 0;
787:     p.onGround = true;
788:     p.jumpsLeft = 1;
789:     p.platform = null;
790:   }
791:   if (p.onGround) p.coyote = 0.1;
792:   else p.coyote = Math.max(0, p.coyote - dt);
793: 
794:   // carry on moving platforms
795:   if (p.onGround && p.platform) {
796:     p.x += (p.platform.vx || 0) * dt;
797:     p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
798:   }
799: 
800:   if (p.onGround && !p.wasGround && p.vy === 0) {
801:     dust(p.x, p.y, 5);
802:     if (Math.abs(p.vx) > 40 * S || state === 'play') sfx.land();
803:   }
804: 
805:   p.runPhase += Math.abs(p.vx) * dt * 0.033;
806: }
