808: function updateAI(p, dt) {
809:   const opp = getOpponent(p);
810:   if (!opp) return;
811:   p.aiTimer -= dt;
812:   p.aiStrafeTimer -= dt;
813:   p.aiJumpCd -= dt;
814: 
815:   if (state === 'title') {
816:     p.demoT += dt;
817:     p.demoThrow -= dt;
818:     const home = arena.left + (arena.right - arena.left) * (p.idx === 0 ? 0.13 : 0.87);
819:     const tx = home + Math.sin(p.demoT * 0.55 + p.idx * 2.1) * 70 * S;
820:     p.aiMove = clamp((tx - p.x) / (70 * S), -1, 1);
821:     if (p.charging) {
822:       p.aiCharge += dt;
823:       if (p.aiCharge > p.aiHold) releaseThrow(p);
824:     } else if (p.demoThrow <= 0 && p.throwCd <= 0 && balls.length < 3) {
825:       beginThrow(p);
826:       p.aiHold = rand(0.35, 0.85);
827:       p.aiCharge = 0;
828:       p.demoThrow = rand(2.4, 4.4);
829:     }
830:     if (p.onGround && Math.random() < dt * 0.18) p.jumpBuffer = 0.1;
831:     return;
832:   }
833: 
834:   if (p.aiStrafeTimer <= 0) {
835:     p.aiStrafe = pick([-1, 0, 1]);
836:     p.aiStrafeTimer = rand(0.7, 1.7);
837:   }
838:   const dx = opp.x - p.x;
839:   const adx = Math.abs(dx);
840:   let move = 0;
841:   if (adx > 460 * S) move = Math.sign(dx);
842:   else if (adx < 200 * S) move = -Math.sign(dx);
843:   else move = p.aiStrafe * 0.65;
844:   if (p.x < arena.left + 70 * S) move = 1;
845:   if (p.x > arena.right - 70 * S) move = -1;
846:   p.aiMove = clamp(move, -1, 1);
847: 
848:   const threat = balls.find(b => !b.dead && b.owner !== p.idx &&
849:     dist(b.x, b.y, p.x, p.y - 42 * S) < 235 * S &&
850:     (b.vx * (p.x - b.x) + b.vy * (p.y - 42 * S - b.y)) > 0);
851:   if (threat && p.onGround && p.aiJumpCd <= 0) {
852:     p.jumpBuffer = 0.12;
853:     p.aiJumpCd = rand(0.9, 1.8);
854:   } else if (p.onGround && p.aiJumpCd <= 0 && adx < 430 * S && Math.random() < dt * 0.35) {
855:     p.jumpBuffer = 0.1;
856:     p.aiJumpCd = rand(1.3, 2.6);
857:   }
858: 
859:   if (p.charging) {
860:     p.aiCharge += dt;
861:     if (p.aiCharge >= p.aiHold || p.charge >= 1) releaseThrow(p);
862:   } else if (p.throwCd <= 0 && p.aiTimer <= 0) {
863:     const catchable = nearbyCatchable(p);
864:     if (catchable && Math.random() < 0.68) {
865:       doCatch(p, catchable);
866:       p.aiTimer = rand(0.7, 1.5);
867:     } else {
868:       beginThrow(p);
869:       p.aiHold = rand(0.28, 0.95);
870:       p.aiCharge = 0;
871:       p.aiTimer = rand(0.55, 1.35);
872:     }
873:   }
874: }
