876: /* ------------------------------ main update ------------------------------ */
877: function update(dtRaw) {
878:   if (paused) return;
879:   gameT += dtRaw;
880:   timeScale = lerp(timeScale, timeScaleTarget, Math.min(1, dtRaw * 8));
881:   if (slowmoT > 0) {
882:     slowmoT -= dtRaw;
883:     if (slowmoT <= 0) timeScaleTarget = 1;
884:   }
885:   if (hitstop > 0) hitstop -= dtRaw;
886:   const sdt = hitstop > 0 ? 0 : dtRaw * timeScale;
887: 
888:   shake = Math.max(0, shake - dtRaw * 46);
889:   const sh = shake;
890:   shakeX = sh > 0.1 ? rand(-sh, sh) : 0;
891:   shakeY = sh > 0.1 ? rand(-sh, sh) : 0;
892: 
893:   // moving platforms
894:   for (const pl of platforms) {
895:     if (!pl.vx) pl.vx = (Math.random() < 0.5 ? -1 : 1) * 60 * S;
896:     pl.x += pl.vx * (hitstop > 0 ? 0 : dtRaw * timeScale);
897:     if (pl.x < arena.left) { pl.x = arena.left; pl.vx = Math.abs(pl.vx); }
898:     if (pl.x + pl.w > arena.right) { pl.x = arena.right - pl.w; pl.vx = -Math.abs(pl.vx); }
899:   }
900:    // keep platforms on the same row from phasing through each other
901:    for (let i = 0; i < platforms.length; i++) {
902:      for (let j = i + 1; j < platforms.length; j++) {
903:        const a = platforms[i], b = platforms[j];
904:        if (Math.abs(a.y - b.y) > 6 * S) continue;
905:        const overlap = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
906:        if (overlap > 0) {
907:          const push = overlap / 2 + 0.5 * S;
908:          a.x -= push; b.x += push;
909:          const va = a.vx; a.vx = b.vx; b.vx = va;
910:          a.x = clamp(a.x, arena.left, arena.right - a.w);
911:          b.x = clamp(b.x, arena.left, arena.right - b.w);
912:        }
913:      }
914:    }
915: 
916:   if (state === 'title') {
917:     for (const p of players) updatePlayer(p, sdt);
918:     updateBalls(sdt);
919:     updateParticles(sdt);
920:     updateFloaters(sdt);
921:     return;
922:   }
923:   if (!match) return;
924: 
