345:     g.strokeStyle = 'rgba(36,19,53,.45)'; g.lineWidth = 1.4; g.stroke();
346:     g.fillStyle = INK;
347:     g.beginPath(); g.arc(9, -75.5, 0.8, 0, TAU); g.fill();
