352: function drawCharacter(g, char, o) {
353:   const s = o.scale || 1;
354:   g.save();
355:   g.scale(s, s);
356:   const run = o.run || 0;
357:   const phase = o.phase || 0;
358:   const t = o.t || 0;
359:   const bob = o.ko ? 0 : o.onGround
360:     ? (run > 0.06 ? Math.abs(Math.sin(phase)) * 2.4 * run : Math.sin(t * 2.1 + (o.seed || 0)) * 1.4)
361:     : -1.5;
362:   g.translate(0, bob);
363:   if ((o.hurt || 0) > 0) g.rotate(-0.09);
364:   if (o.charging) g.translate(rand(-0.9, 0.9), rand(-0.9, 0.9));
365:   g.scale(o.facing || 1, 1);
366: 
367:   drawLegs(g, char, o);
368:   drawArm(g, char, o, -(o.aim || 1), false);
369:   drawBody(g, char, o);
370:   drawAnimalHead(g, char, o);
371:   drawArm(g, char, o, (o.aim || 1), true);
372:   g.restore();
373: }
