375: function drawPlayer(p, t) {
376:   const opp = getOpponent(p);
377:   const color = playerColor(p);
378:   const lookX = opp ? clamp((opp.x - p.x) / (260 * S), -1, 1) * p.facing : 0;
379:   const lookY = opp ? clamp(((opp.y - 42 * S) - (p.y - 52 * S)) / (260 * S), -1, 1) : 0;
380:   const aimSign = opp ? (Math.sign(opp.x - p.x) || 1) : p.facing;
381: 
382:   if ((p.onGround || p.ko) && state !== 'title') {
383:     ctx.beginPath();
384:     ctx.ellipse(p.x, p.y + 2 * S, 26 * S, 6 * S, 0, 0, TAU);
385:     ctx.fillStyle = 'rgba(36,19,53,.22)';
386:     ctx.fill();
387:   }
388: 
389:   if (p.rageT > 0) {
390:     const cx = p.x, cy = p.y - 42 * S;
391:     const bob = Math.sin(t * 5) * 6 * S;
392:     const glowR = 62 * S + Math.sin(t * 7) * 8 * S;
393:     const glow = ctx.createRadialGradient(cx, cy + bob, 8 * S, cx, cy + bob, glowR);
394:     glow.addColorStop(0, 'rgba(255,220,100,0.5)');
395:     glow.addColorStop(0.5, 'rgba(255,120,20,0.25)');
396:     glow.addColorStop(1, 'rgba(255,60,0,0)');
397:     ctx.fillStyle = glow;
398:     ctx.beginPath(); ctx.arc(cx, cy + bob, glowR, 0, TAU); ctx.fill();
399: 
400:     const pulse = 1 + Math.sin(t * 8) * 0.15 + Math.sin(t * 13) * 0.06;
401:     const rot = Math.sin(t * 4) * 0.12;
402:     ctx.save();
403:     ctx.translate(cx, cy + bob);
404:     ctx.rotate(rot);
405:     ctx.globalAlpha = 1;
406:     ctx.font = `${104 * S * pulse}px serif`;
407:     ctx.textAlign = 'center';
408:     ctx.textBaseline = 'middle';
409:     ctx.fillText('🔥', 0, 0);
410:     ctx.restore();
411:   }
412:   if (p.shieldT > 0) {
413:     ctx.beginPath();
414:     ctx.arc(p.x, p.y - 42 * S, 52 * S, 0, TAU);
415:     ctx.fillStyle = `rgba(125,211,252,${0.18 + Math.sin(t * 8) * 0.05})`;
416:     ctx.fill();
417:     ctx.lineWidth = 3 * S;
418:     ctx.strokeStyle = 'rgba(14,165,233,.85)';
419:     ctx.stroke();
420:   }
421:   ctx.save();
422:   ctx.translate(p.x, p.y);
423:   if (p.invuln > 0 && state === 'play' && Math.floor(p.invuln * 22) % 2 === 0) ctx.globalAlpha = 0.55;
424:   if (p.ko) {
425:     const k = clamp(p.koT / 0.9, 0, 1);
426:     ctx.rotate(k * Math.PI * 0.48 * (p.koDir || 1));
427:   }
428:   drawCharacter(ctx, p.char, {
429:     scale: S,
430:     facing: p.facing,
431:     t, phase: p.runPhase, run: p.onGround ? clamp(Math.abs(p.vx) / (runSpeedFor() || 1), 0, 1) : 0.4,
432:     onGround: p.onGround, vy: p.vy, seed: p.idx * 2.3,
433:     aiming: true, aim: aimSign * p.facing,
434:     charging: p.charging, charge: p.charge,
435:     throwAnim: p.throwAnim, catchAnim: p.catchAnim,
436:     hurt: p.hitstun, ko: p.ko,
437:     lookX, lookY,
438:     blink: p.blink > 0,
439:     color,
440:     showBall: !p.ko && p.throwAnim <= 0 && p.throwCd <= 0,
441:     ballRadius: 7.5 + p.charge * 7,
442:   });
443:   ctx.restore();
444: 
445:   // player ID badge above the head
446:   if (state !== 'title' && state !== 'matchEnd') {
447:     const bw = Math.max(15, 18 * S), bh = Math.max(11, 13 * S);
448:     const by = p.y - 104 * S;
449:     ctx.save();
450:     ctx.translate(p.x, by);
451:     rr(ctx, -bw / 2, -bh / 2, bw, bh, 7 * S);
452:     ctx.fillStyle = color;
453:     ctx.fill();
454:     ctx.lineWidth = 2.4 * S;
455:     ctx.strokeStyle = INK;
456:     ctx.stroke();
457:     ctx.beginPath();
458:     ctx.moveTo(-3.4 * S, bh / 2 - 1);
459:     ctx.lineTo(0, bh / 2 + 5 * S);
460:     ctx.lineTo(3.4 * S, bh / 2 - 1);
461:     ctx.closePath();
462:     ctx.fillStyle = color; ctx.fill();
463:     ctx.strokeStyle = INK; ctx.lineWidth = 2.2 * S; ctx.stroke();
464:     ctx.font = `${Math.max(8, 10 * S)}px Bungee, sans-serif`;
465:     ctx.textAlign = 'center';
466:     ctx.textBaseline = 'middle';
467:     ctx.fillStyle = p.idx === 0 ? INK : CREAM;
468:     ctx.fillText(String(p.idx + 1), 0, 0.6 * S);
469:     ctx.restore();
470:   }
471:   if (state === 'play' && !p.ko) {
472:     const b = nearbyCatchable(p);
473:     if (b && !p.charging) {
474:       const r = 66 * S + Math.sin(t * 8 + p.idx) * 3 * S;
475:       ctx.beginPath(); ctx.arc(p.x, p.y - 40 * S, r, 0, TAU);
476:       ctx.strokeStyle = withA(color, 0.5);
477:       ctx.lineWidth = 2.5 * S;
478:       ctx.setLineDash([5 * S, 6 * S]);
479:       ctx.stroke();
480:       ctx.setLineDash([]);
481:       ctx.font = `${9 * S}px Bungee, sans-serif`;
482:       ctx.textAlign = 'center';
483:       ctx.lineWidth = 3 * S;
484:       ctx.strokeStyle = 'rgba(36,19,53,.8)';
485:       ctx.strokeText('CATCH!', p.x, p.y + 24 * S);
486:       ctx.fillStyle = CREAM;
487:       ctx.fillText('CATCH!', p.x, p.y + 24 * S);
488:     }
489:   }
490: 
491:   // KO stars
492:   if (p.ko) {
493:     for (let i = 0; i < 3; i++) {
494:       const a = t * 3.4 + i * TAU / 3;
495:       const sx = p.x + Math.cos(a) * 22 * S;
496:       const sy = p.y - 82 * S + Math.sin(a) * 9 * S;
497:       ctx.save(); ctx.translate(sx, sy); ctx.rotate(a);
498:       starPath(ctx, 6 * S, 2.6 * S, 5);
499:       ctx.fillStyle = '#ffd23f'; ctx.fill();
500:       ctx.lineWidth = 1.6 * S; ctx.strokeStyle = INK; ctx.stroke();
501:       ctx.restore();
502:     }
503:   }
504: }
