511:   const sunX = W * 0.74, sunY = arena.top + (floorY - arena.top) * 0.22;
512:   const sunR = Math.min(W, H) * 0.072;
513:   ctx.save();
514:   ctx.translate(sunX, sunY);
515:   ctx.rotate(t * 0.018);
516:   ctx.fillStyle = 'rgba(255,236,168,.055)';
517:   for (let i = 0; i < 16; i++) {
518:     const a = i * TAU / 16;
519:     ctx.beginPath();
520:     ctx.moveTo(0, 0);
521:     ctx.arc(0, 0, Math.max(W, H) * 0.7, a, a + 0.1);
522:     ctx.closePath();
523:     ctx.fill();
524:   }
525:   ctx.restore();
526: 
527:   const glow = ctx.createRadialGradient(sunX, sunY, sunR * 0.2, sunX, sunY, sunR * 2.8);
528:   glow.addColorStop(0, 'rgba(255,239,177,.55)');
529:   glow.addColorStop(0.5, 'rgba(255,199,110,.16)');
530:   glow.addColorStop(1, 'rgba(255,160,90,0)');
531:   ctx.fillStyle = glow;
532:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR * 2.8, 0, TAU); ctx.fill();
533:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR, 0, TAU);
534:   ctx.fillStyle = '#ffedb0'; ctx.fill();
535:   ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,244,216,.55)'; ctx.stroke();
536: 
537:   // stars
538:   for (const st of stars) {
539:     const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * st.sp + st.ph));
540:     ctx.beginPath(); ctx.arc(st.x, st.y, st.r, 0, TAU);
541:     ctx.fillStyle = `rgba(255,244,216,${tw * 0.65})`; ctx.fill();
542:   }
543: 
544:   // clouds
545:   ctx.fillStyle = 'rgba(255,220,190,.18)';
546:   for (const c of clouds) {
547:     const x = ((c.x + t * c.sp + 160) % (W + 320)) - 160;
548:     const y = c.y + Math.sin(t * 0.4 + c.ph) * 3;
549:     ctx.globalAlpha = c.a;
550:     ctx.beginPath();
551:     ctx.ellipse(x, y, 46 * c.s, 15 * c.s, 0, 0, TAU);
552:     ctx.ellipse(x + 34 * c.s, y - 8 * c.s, 30 * c.s, 17 * c.s, 0, 0, TAU);
553:     ctx.ellipse(x - 36 * c.s, y - 4 * c.s, 26 * c.s, 13 * c.s, 0, 0, TAU);
554:     ctx.fill();
555:     ctx.globalAlpha = 1;
556:   }
557: }
