731: function drawPlatforms(t) {
732:   for (const p of platforms) {
733:     // short hanging chains under the ends (no ceiling clutter)
734:     for (const fx of [0.16, 0.84]) {
735:       const x = p.x + p.w * fx;
736:       const topY = p.y + p.h;
737:       ctx.strokeStyle = 'rgba(36,19,53,.42)';
738:       ctx.lineWidth = 2.4 * S;
739:       ctx.beginPath(); ctx.moveTo(x, topY - 1); ctx.lineTo(x, topY + 6 * S); ctx.stroke();
740:       for (let k = 0; k < 3; k++) {
741:         const cy = topY + (11 + k * 11) * S + Math.sin(t * 1.8 + k * 0.7 + p.x * 0.01) * 0.7 * S;
742:         ctx.beginPath();
743:         ctx.ellipse(x, cy, 2.4 * S, 5.2 * S, 0, 0, TAU);
744:         ctx.strokeStyle = k === 2 ? 'rgba(36,19,53,.24)' : 'rgba(36,19,53,.32)';
745:         ctx.lineWidth = 1.6 * S;
746:         ctx.stroke();
747:       }
748:     }
749: 
750:     // ground shadow
751:     ctx.beginPath();
752:     ctx.ellipse(p.x + p.w / 2, p.y + p.h + 6 * S, p.w * 0.44, 5.5 * S, 0, 0, TAU);
753:     ctx.fillStyle = 'rgba(14,6,26,.26)'; ctx.fill();
754: 
755:     // body
756:     rr(ctx, p.x, p.y, p.w, p.h, 5 * S);
757:     ctx.fillStyle = '#e2ab60'; ctx.fill();
758:     ctx.lineWidth = 3.5 * S; ctx.strokeStyle = INK; ctx.stroke();
759: 
760:     // lower shade
761:     ctx.save();
762:     rr(ctx, p.x, p.y, p.w, p.h, 5 * S);
763:     ctx.clip();
764:     ctx.fillStyle = 'rgba(128,76,32,.22)';
765:     ctx.fillRect(p.x, p.y + p.h * 0.58, p.w, p.h);
766:     // top surface
767:     ctx.fillStyle = '#ffe0a0';
768:     ctx.fillRect(p.x, p.y + 1, p.w, 5 * S);
769:     ctx.fillStyle = 'rgba(255,255,255,.4)';
770:     ctx.fillRect(p.x + 2 * S, p.y + 1.5 * S, p.w - 4 * S, 1.6 * S);
771:     // plank seams
772:     ctx.strokeStyle = 'rgba(120,72,30,.42)';
773:     ctx.lineWidth = 1.6 * S;
774:     const step = Math.max(30 * S, p.w / 4);
775:     for (let x = p.x + step; x < p.x + p.w - 4 * S; x += step) {
776:       ctx.beginPath(); ctx.moveTo(x, p.y + 7 * S); ctx.lineTo(x, p.y + p.h - 3 * S); ctx.stroke();
777:     }
