110: function collideBallRect(b, pl) {
111:   const nx = clamp(b.x, pl.x, pl.x + pl.w);
112:   const ny = clamp(b.y, pl.y, pl.y + pl.h);
113:   const dx = b.x - nx, dy = b.y - ny;
114:   const d2 = dx * dx + dy * dy;
115:   if (d2 > b.r * b.r) return false;
116:   let nX, nY;
117:   const d = Math.sqrt(d2);
118:   if (d < 0.001) {
119:     const l = b.x - pl.x, r = pl.x + pl.w - b.x, t = b.y - pl.y, bo = pl.y + pl.h - b.y;
120:     const m = Math.min(l, r, t, bo);
121:     if (m === l) { nX = -1; nY = 0; b.x = pl.x - b.r; }
122:     else if (m === r) { nX = 1; nY = 0; b.x = pl.x + pl.w + b.r; }
123:     else if (m === t) { nX = 0; nY = -1; b.y = pl.y - b.r; }
124:     else { nX = 0; nY = 1; b.y = pl.y + pl.h + b.r; }
125:   } else {
126:     nX = dx / d; nY = dy / d;
127:     b.x = nx + nX * b.r;
128:     b.y = ny + nY * b.r;
129:   }
130:   const dot = b.vx * nX + b.vy * nY;
131:   if (dot >= 0) return false;
132:   b.vx -= (1 + b.rest) * dot * nX;
133:   b.vy -= (1 + b.rest) * dot * nY;
134:   b.vx *= 0.995;
135:   b.vy *= 0.995;
136:   b.spin += rand(-5, 5);
